import Foundation
import Testing
@testable import VideoTool

// Interface languages (user, 2026-10-19: add at least English and Japanese).
// Chinese is the source; the tables are generated by tools/i18n.py.
@Suite(.serialized) struct LocalizationTests {
    private static let specifier = try! NSRegularExpression(pattern: #"%(?:\d+\$)?(?:@|d|ld|lld|\.\d+f|f)"#)
    private func specifiers(_ s: String) -> [String] {
        Self.specifier.matches(in: s, range: NSRange(s.startIndex..., in: s))
            .map { (s as NSString).substring(with: $0.range).replacingOccurrences(of: #"\d+\$"#, with: "", options: .regularExpression) }
            .sorted()
    }
    private func table(_ lang: String) throws -> [String: String] {
        let bundle = try #require(Localization.bundle(for: lang), "\(lang).lproj missing from the app")
        let url = try #require(bundle.url(forResource: "Localizable", withExtension: "strings"))
        return try #require(NSDictionary(contentsOf: url) as? [String: String])
    }

    @Test("I1 the app offers Chinese, English and Japanese; tests read Chinese") func languages() {
        #expect(Set(Bundle.main.localizations).isSuperset(of: ["zh-Hans", "en", "ja"]))
        #expect(L("全部视频") == "全部视频")
        #expect(L("共 %@ 个视频", "3") == "共 3 个视频")
    }

    @Test("I2 every interface string in the source code is in the tables (run tools/i18n.py extract/build)")
    func noMissingKeys() throws {
        let sources = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().appendingPathComponent("App/Sources")
        let key = try NSRegularExpression(pattern: #"\bL\("((?:[^"\\]|\\.)*)""#)
        var used = Set<String>()
        for case let url as URL in FileManager.default.enumerator(at: sources, includingPropertiesForKeys: nil)!
            where url.pathExtension == "swift" {
            let text = try String(contentsOf: url, encoding: .utf8)
            for m in key.matches(in: text, range: NSRange(text.startIndex..., in: text)) {
                let raw = (text as NSString).substring(with: m.range(at: 1))
                used.insert(raw.replacingOccurrences(of: #"\n"#, with: "\n").replacingOccurrences(of: #"\""#, with: "\""))
            }
        }
        let zh = try table("zh-Hans")
        #expect(used.subtracting(zh.keys).sorted() == [], "add them with tools/i18n.py extract && build")
        #expect(used.count > 150, "the scan found the interface strings (173 on 2026-10-19; tag names come on top)")
    }

    @Test("I3 English and Japanese: every string translated, placeholders kept, no Chinese left in English",
          arguments: ["en", "ja"])
    func complete(lang: String) throws {
        let zh = try table("zh-Hans"), t = try table(lang)
        for key in zh.keys {
            let value = try #require(t[key], "\(lang) missing: \(key)")
            #expect(!value.isEmpty, "\(lang) empty: \(key)")
            #expect(specifiers(value) == specifiers(key), "\(lang) placeholders differ: \(key) → \(value)")
            if lang == "en" { #expect(value.range(of: #"[\p{Han}]"#, options: .regularExpression) == nil, "Chinese in en: \(value)") }
        }
    }

    @Test("I4 switching the bundle switches the interface: menus read naturally in each language") func rendering() throws {
        // A task-local override: the global bundle stays Chinese for suites running alongside.
        try Localization.$override.withValue(try #require(Localization.bundle(for: "en"))) {
            #expect(L("关于 VideoTool") == "About VideoTool")
            #expect(L("共 %@ 个视频", "3").contains("3"))
            #expect(LibraryGroupingMode.all.title == L("全部视频") && LibraryGroupingMode.all.title != "全部视频")
        }
        try Localization.$override.withValue(try #require(Localization.bundle(for: "ja"))) {
            #expect(L("关于 VideoTool") == "VideoToolについて")
            #expect(L("文件") == "ファイル")
        }
        #expect(L("文件") == "文件", "outside the override: unchanged")
    }
}
